package net.civeira.phylax.feature.observe.observedissuecomment.domain.gateway;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssueReference;

class ObservedIssueCommentFilterUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_observed_issue_comment_filter_builder() {
    ObservedIssueCommentFilter filter = ObservedIssueCommentFilter.builder().build();
    Assertions.assertFalse(filter.getUid().isPresent(),
        "Uid must be empty if filter is build without it");
    filter.setUid("one");
    Assertions.assertEquals("one", filter.getUid().get(), "Uid must be the same as the assigned");
    Assertions.assertTrue(filter.getUids().isEmpty(),
        "Uid must be empty if filter is build without it");
    filter.setUids(List.of("one"));
    Assertions.assertEquals(List.of("one"), filter.getUids(),
        "Uids must be the same as the assigned");
    Assertions.assertFalse(filter.getSearch().isPresent(),
        "Search must be empty if filter is build without it");
    filter.setSearch("lookup");
    Assertions.assertEquals("lookup", filter.getSearch().get(),
        "Search must be the same as the assigned");
    Assertions.assertFalse(filter.getIssue().isPresent(),
        "Issue must be empty if filter is build without it");
    filter.setIssue(ObservedIssueReference.of("$ref"));
    Assertions.assertEquals(ObservedIssueReference.of("$ref"), filter.getIssue().get(),
        "Issue must be the same as the assigned");
    Assertions.assertFalse(filter.getAuthorName().isPresent(),
        "AuthorName must be empty if filter is build without it");
    filter.setAuthorName("one");
    Assertions.assertEquals("one", filter.getAuthorName().get(),
        "AuthorName must be the same as the assigned");
  }
}
